import { createHmac, randomBytes } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import type { APIRequestContext, APIResponse } from '@playwright/test';
import { STUB_CHANNEL_SECRET } from '../fixtures/line/credentials';

/** Values substituted into the `{{placeholders}}` of a webhook fixture. */
export type FixtureVars = {
  userId: string;
  messageId: string;
  messageId2: string;
  /** Needed only by `burst-three-texts`; generated by `newFixtureVars`. */
  messageId3?: string;
  webhookEventId: string;
  webhookEventId2: string;
  webhookEventId3: string;
  replyToken: string;
  timestamp: number;
  text?: string;
  /** Texts of the second and third event of `burst-three-texts`; default to `text` + " 2" / " 3". */
  text2?: string;
  text3?: string;
  /** LINE id of the quoted message of `message-text-quote`; a fresh id when not given. */
  quotedMessageId?: string;
  /** `postback.data` of `postback`; the data of the "วิธีทดสอบ" button when not given. */
  postbackData?: string;
};

const DESTINATION = 'Ustub00000000000000000000000000000';
const DEFAULT_TEXT = 'hello';
const FIXTURE_DIR = fileURLToPath(new URL('../fixtures/line/', import.meta.url));
const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';

/** 26-character ULID: 48-bit time and 80 random bits, Crockford base32. */
function newUlid(now: number): string {
  let time = '';
  let rest = now;
  for (let i = 0; i < 10; i += 1) {
    time = CROCKFORD.charAt(rest % 32) + time;
    rest = Math.floor(rest / 32);
  }
  const random = randomBytes(16);
  let tail = '';
  for (let i = 0; i < 16; i += 1) tail += CROCKFORD.charAt((random[i] ?? 0) % 32);
  return time + tail;
}

/** 18 decimal digits, never starting with 0. */
function newMessageId(): string {
  const n = randomBytes(8).readBigUInt64BE() % 900_000_000_000_000_000n;
  return String(n + 100_000_000_000_000_000n);
}

/** Fresh, unique values for one fixture; `overrides` win over the generated values. */
export function newFixtureVars(overrides: Partial<FixtureVars> = {}): FixtureVars {
  const timestamp = overrides.timestamp ?? Date.now();
  return {
    userId: `U${randomBytes(16).toString('hex')}`,
    messageId: newMessageId(),
    messageId2: newMessageId(),
    messageId3: newMessageId(),
    webhookEventId: newUlid(timestamp),
    webhookEventId2: newUlid(timestamp),
    webhookEventId3: newUlid(timestamp),
    replyToken: randomBytes(16).toString('hex'),
    timestamp,
    ...overrides,
  };
}

/**
 * Fills a template of `e2e/fixtures/line/` and returns the raw body to send. Placeholders that
 * stand for a number or a JSON string (`timestamp`, `timestamp+<ms>`, `text`, `text2`, `text3`)
 * are written as quoted strings in the file so the template is valid JSON (and passes Prettier);
 * the quotes are dropped here. The result is parsed once to prove it is valid JSON, but the
 * substituted text is returned unchanged because the signature covers the exact bytes sent.
 */
export function renderFixture(name: string, vars: FixtureVars): string {
  const file = name.endsWith('.json') ? name : `${name}.json`;
  if (file.includes('/') || file.includes('\\')) throw new Error(`Invalid fixture name: ${name}`);
  const template = readFileSync(`${FIXTURE_DIR}${file}`, 'utf8');
  const text = vars.text ?? DEFAULT_TEXT;
  const strings: Record<string, string> = {
    destination: DESTINATION,
    userId: vars.userId,
    messageId: vars.messageId,
    messageId2: vars.messageId2,
    messageId3: vars.messageId3 ?? newMessageId(),
    webhookEventId: vars.webhookEventId,
    webhookEventId2: vars.webhookEventId2,
    webhookEventId3: vars.webhookEventId3,
    replyToken: vars.replyToken,
    quotedMessageId: vars.quotedMessageId ?? newMessageId(),
    postbackData: vars.postbackData ?? 'tw1:how_to',
  };
  const jsonTexts: Record<string, string> = {
    text,
    text2: vars.text2 ?? `${text} 2`,
    text3: vars.text3 ?? `${text} 3`,
  };
  const body = template.replace(
    /(")?\{\{(\w+)(?:\+(\d+))?\}\}(")?/g,
    (
      _match,
      open: string | undefined,
      key: string,
      offset: string | undefined,
      close: string | undefined,
    ) => {
      if (key === 'timestamp') return String(vars.timestamp + Number(offset ?? 0));
      const json = jsonTexts[key];
      if (json !== undefined && offset === undefined) return JSON.stringify(json);
      const value = strings[key];
      if (value === undefined || offset !== undefined) {
        throw new Error(`Unknown placeholder {{${key}}} in fixture ${file}`);
      }
      return `${open ?? ''}${value}${close ?? ''}`;
    },
  );
  JSON.parse(body);
  return body;
}

/** `x-line-signature`: base64(HMAC-SHA256(channelSecret, rawBody)). */
export function signLineBody(rawBody: string, channelSecret: string): string {
  return createHmac('sha256', channelSecret).update(rawBody, 'utf8').digest('base64');
}

/** POSTs a rendered, signed fixture to `/api/line/webhook`. */
export async function postLineWebhook(
  request: APIRequestContext,
  name: string,
  vars: FixtureVars,
  opts: { signature?: string; channelSecret?: string } = {},
): Promise<APIResponse> {
  const body = renderFixture(name, vars);
  const secret = opts.channelSecret ?? process.env.E2E_LINE_CHANNEL_SECRET ?? STUB_CHANNEL_SECRET;
  return request.post('/api/line/webhook', {
    headers: {
      'content-type': 'application/json',
      'x-line-signature': opts.signature ?? signLineBody(body, secret),
    },
    data: body,
  });
}
